(window.__ATLAS_DATA=window.__ATLAS_DATA||{})["data/acts/L140.json"]={"meta":{"id":"L140","name":"Legea privind protecția specială a copiilor aflați în situație de risc și a copiilor separați de părinți","short":"Legea nr. 140/2013","type":"Lege","number":"140/2013","date":"14.06.2013","published":"Publicat : 02.08.2013 în MONITORUL OFICIAL Nr. 167-172 art. 534 Data intrării în vigoare","lastAmend":"LP167 din 30.07.26, MO435-438/09.09.26 art. 452; în vigoare 09.12.26","aliases":["lege:140/2013"],"titleRaw":"privind protecţia specială a copiilor aflaţi în situaţie de risc şi a copiilor separaţi de părinţi","signature":["PREȘEDINTELE PARLAMENTULUI Igor CORMAN","Nr. 140. Chișinău, 14 iunie 2013."],"preamble":["MODIFICAT","LP167 din 30.07.26, MO435-438/09.09.26 art. 452; în vigoare 09.12.26","Parlamentul adoptă prezenta lege organică."]},"nodes":[{"id":"n1","kind":"capitol","lvl":3,"label":"Capitolul I","name":"DISPOZIŢII GENERALE","parent":null,"arts":["1","2","3","4","5"]},{"id":"n2","kind":"capitol","lvl":3,"label":"Capitolul II","name":"ATRIBUŢIILE AUTORITĂŢILOR TUTELARE ÎN DOMENIUL PROTECŢIEI COPILULUI","parent":null,"arts":["6","7","7_1"]},{"id":"n3","kind":"capitol","lvl":3,"label":"Capitolul III","name":"IDENTIFICAREA, EVIDENŢA ŞI ASISTENŢA COPIILOR AFLAȚI ÎN SITUAŢIE DE RISC","parent":null,"arts":["8","9","10"]},{"id":"n4","kind":"capitol","lvl":3,"label":"Capitolul IV","name":"PROTECŢIA COPIILOR SEPARAŢI DE PĂRINŢI","parent":null,"arts":["11","12","12_1","12_2","12_3","12_4","13","13_1","13_2","13_3","13_4","13_5","13_6"]},{"id":"n5","kind":"capitol","lvl":3,"label":"Capitolul V","name":"DETERMINAREA STATUTULUI COPILULUI","parent":null,"arts":["14","15","16","17","18"]},{"id":"n6","kind":"capitol","lvl":3,"label":"Capitolul VI","name":"COOPERAREA ÎN DOMENIUL PROTECŢIEI COPILULUI","parent":null,"arts":["19","20"]},{"id":"n7","kind":"capitol","lvl":3,"label":"Capitolul VII","name":"RĂSPUNDEREA","parent":null,"arts":["21","22"]},{"id":"n8","kind":"capitol","lvl":3,"label":"Capitolul VIII","name":"DISPOZIŢII FINALE ŞI TRANZITORII","parent":null,"arts":["23"]}],"articles":[{"id":"1","num":"1","title":"Obiectul legii","node":"n1","blocks":[{"k":"p","id":"x1","t":"Prezenta lege stabileşte procedurile de identificare, evaluare, asistenţă, referire, monitorizare şi evidenţă a copiilor aflați în situaţie de risc şi a copiilor separaţi de părinţi, precum şi autorităţile şi structurile responsabile de aplicarea procedurilor respective.","lvl":1}]},{"id":"2","num":"2","title":"Sfera de aplicare","node":"n1","blocks":[{"k":"p","id":"x1","t":"În condiţiile prezentei legi, copiii beneficiază de protecţie fără nicio discriminare, indiferent de rasă, culoare, sex, limbă, religie, opinii politice sau de altă natură, de cetăţenie, apartenenţa etnică sau originea socială, de statutul obținut prin naştere, de situaţia materială, de gradul şi tipul de dizabilitate, de aspectele specifice de creştere şi educaţie a copiilor, a părinţilor lor, reprezentanților legali ori responsabililor legali ai acestora, de locul aflării lor (familie, instituţie educaţională, serviciu social, instituţie medicală, comunitate etc.).","lvl":1}]},{"id":"3","num":"3","title":"Noţiuni principale","node":"n1","blocks":[{"k":"p","id":"x1","t":"În sensul prezentei legi, noţiunile principale utilizate au următoarele semnificaţii:","lvl":1},{"k":"p","id":"x2","t":"autoritate centrală pentru protecţia copilului – Ministerul Muncii și Protecției Sociale, abilitat să elaboreze, să promoveze şi să monitorizeze realizarea politicii statului în domeniul protecţiei copilului;","lvl":1,"def":"autoritate centrală pentru protecţia copilului"},{"k":"p","id":"x3","t":"autoritate tutelară locală – primarii de sate (comune) și de oraşe;","lvl":1,"def":"autoritate tutelară locală"},{"k":"p","id":"x4","t":"autoritate tutelară teritorială – agenția teritorială de asistență socială (prin intermediul structurilor teritoriale de asistență socială), Direcția generală pentru protecția drepturilor copilului din Chișinău, Direcția principală a sănătății și protecției sociale din unitatea teritorială autonomă Găgăuzia. În municipiile Chișinău și Bălți, autoritățile tutelare teritoriale exercită și atribuțiile de autoritate tutelară locală, cu excepția unităților administrativ-teritoriale autonome din componența acestora, în cadrul cărora atribuțiile de autoritate tutelară locală sunt exercitate de primarii unităților administrativ-teritoriale respective;","lvl":1,"def":"autoritate tutelară teritorială"},{"k":"p","id":"x5","t":"copil – persoană care nu a împlinit vârsta de 18 ani şi nu are capacitatea de exerciţiu deplină;","lvl":1,"def":"copil"},{"k":"p","id":"x6","t":"copil aflat în situaţie de risc – copil în privința căruia, ca urmare a evaluării, se constată una sau mai multe din situațiile prevăzute la art. 8;","lvl":1,"def":"copil aflat în situaţie de risc","r":[[141,147,{"art":"8"}]]},{"k":"p","id":"x7","t":"copil separat de părinți – copil lipsit efectiv de grija părinților/unicului părinte în situații determinate de aflarea motivată a acestora în altă localitate din țară sau de peste hotare pentru o perioadă mai mare de 2 luni consecutive; copil luat de la părinți din cauza unui pericol iminent pentru viața sau sănătatea acestuia; copil căruia i s-a stabilit statut de copil rămas temporar fără ocrotire părintească sau de copil rămas fără ocrotire părintească;","lvl":1,"def":"copil separat de părinți"},{"k":"p","id":"x8","t":"copil abandonat – copilul identificat ca fiind fără părinţi sau fără alt însoţitor legal în cazul în care nu pot fi stabilite datele de identitate nici ale copilului, nici ale părinţilor lui;","lvl":1,"def":"copil abandonat"},{"k":"p","id":"x9","t":"interesul superior al copilului – asigurarea condițiilor adecvate pentru creșterea și dezvoltarea armonioasă a copilului, ținând cont de particularitățile individuale ale personalității lui și de situația concretă în care acesta se află;","lvl":1,"def":"interesul superior al copilului"},{"k":"p","id":"x10","t":"familie – părinţii şi copiii acestora;","lvl":1,"def":"familie"},{"k":"p","id":"x11","t":"familie extinsă – rudele copilului până la gradul IV inclusiv;","lvl":1,"def":"familie extinsă"},{"k":"p","id":"x12","t":"reprezentant legal al copilului – părintele copilului, persoană sau autoritate, desemnată, conform legii, să apere drepturile și interesele legitime ale copilului și să acționeze în numele copilului în materie de protecție, siguranță, ocrotire a sănătății, educație, proprietate și în alte domenii;","lvl":1,"def":"reprezentant legal al copilului"},{"k":"p","id":"x13","t":"management de caz – metoda principală de lucru a specialistului în protecția drepturilor copilului sau a asistentului social, cu ajutorul căreia acesta evaluează necesităţile copilului şi ale familiei lui în colaborare cu ei, coordonează, monitorizează, evaluează şi susţine copilul şi familia acestuia pentru ca ei să poată beneficia de serviciile şi prestaţiile sociale care să răspundă acestor necesităţi;","lvl":1,"def":"management de caz"},{"k":"p","id":"x14","t":"echipă multidisciplinară – grup convocat de specialistul în protecția drepturilor copilului sau, în lipsa acestuia, de către asistentul social comunitar, compus din profesionişti din diferite domenii, cu atribuţii în protecţia copilului, care colaborează în scopul prevenirii şi/sau soluţionării cazurilor copiilor aflați în situații de risc;","lvl":1,"def":"echipă multidisciplinară"},{"k":"p","id":"x15","t":"plan individual de asistenţă – document prin care se realizează planificarea serviciilor, a prestaţiilor şi a măsurilor de protecţie a copilului în baza evaluării complexe a acestuia şi a familiei sale;","lvl":1,"def":"plan individual de asistenţă"},{"k":"p","id":"x16","t":"violenţă împotriva copilului – forme de rele tratamente aplicate de către părinţi/reprezentanţii legali/persoana în grija căreia se află copilul sau de către orice altă persoană, care produc vătămare actuală sau potenţială asupra sănătăţii acestuia şi îi pun în pericol viaţa, dezvoltarea, demnitatea sau moralitatea, care includ tipurile de violență definite în art. 2 din Legea nr. 45-XVI din 1 martie 2007 cu privire la prevenirea și combaterea violenței în familie;","lvl":1,"def":"violenţă împotriva copilului","r":[[363,369,{"art":"2","a":"lege:45/2007"}],[374,408,{"a":"lege:45/2007","whole":true}]]},{"k":"p","id":"x17","t":"neglijarea copilului – omisiunea sau ignorarea voluntară sau involuntară a responsabilităţilor privind creşterea și educarea copilului, fapt care pune în pericol dezvoltarea lui fizică, mintală, spirituală, morală sau socială, integritatea lui corporală, sănătatea lui fizică sau psihică. Neglijarea poate lua următoarele forme:","lvl":1,"def":"neglijarea copilului"},{"k":"lit","n":"a","id":"la","t":"neglijare alimentară – privarea copilului de hrană sau malnutriția acestuia;","lvl":1,"def":"neglijare alimentară"},{"k":"lit","n":"b","id":"lb","t":"neglijare vestimentară – lipsa de îmbrăcăminte şi/sau de încălţăminte, în special a celor necesare pentru perioada rece a anului;","lvl":1,"def":"neglijare vestimentară"},{"k":"lit","n":"c","id":"lc","t":"neglijare a igienei – nerespectarea normelor generale de igienă personală, condiții de locuit insalubre, care amenință viața sau sănătatea copilului;","lvl":1,"def":"neglijare a igienei"},{"k":"lit","n":"d","id":"ld","t":"neglijare medicală – lipsa ori refuzul îngrijirilor medicale necesare pentru protecția vieții, integrității corporale și a sănătății copilului, neadresarea la medici în cazuri de urgenţă;","lvl":1,"def":"neglijare medicală"},{"k":"lit","n":"e","id":"le","t":"neglijare educaţională – refuzul încadrării copilului într-o instituție școlară, neşcolarizarea copilului;","lvl":1,"def":"neglijare educaţională"},{"k":"lit","n":"f","id":"lf","t":"neglijare emoţională – ignorarea problemelor psihoemoționale ale copilului;","lvl":1,"def":"neglijare emoţională"},{"k":"lit","n":"g","id":"lg","t":"neglijare în supraveghere – punerea sau lăsarea copilului în condiții ori circumstanțe în care lipsa de supraveghere poate conduce la îmbolnăvirea copilului, traumatismul copilului, exploatarea copilului sau decesul acestuia;","lvl":1,"def":"neglijare în supraveghere"},{"k":"p","id":"x18","t":"pericol iminent – circumstanțe care indică în mod cert asupra existenței situației de risc, inclusiv asupra prezenței elementelor constitutive ale unei infracțiuni contra vieții și/sau sănătății copilului sau asupra riscului apariției acestora în perioada imediat următoare, care au sau pot avea impact grav asupra integrității fizice și/sau psihice a copilului;","lvl":1,"def":"pericol iminent"},{"k":"p","id":"x19","t":"luarea copilului de la părinți – procedură prin care copilul este separat de părinți sau de persoanele în grija cărora acesta se află, efectuată în conformitate cu prevederile prezentei legi și ale Codului familiei;","lvl":1,"def":"luarea copilului de la părinți","r":[[198,214,{"a":"cod:familiei","whole":true}]]},{"k":"p","id":"x20","t":"plasament – măsură de protecţie a copilului separat de părinţi prin care se asigură condiţii pentru creşterea şi îngrijirea acestuia în servicii sociale de plasament;","lvl":1,"def":"plasament"},{"k":"p","id":"x21","t":"plasament de urgenţă – plasamentul copilului ale cărui viaţă sau sănătate sunt în pericol iminent, indiferent de mediul în care acesta se află, pentru o perioadă de până la 72 de ore;","lvl":1,"def":"plasament de urgenţă"},{"k":"p","id":"x22","t":"plasament planificat – plasamentul copilului într-un serviciu social, pentru o perioadă determinată de timp, conform prevederilor planului individual de asistenţă;","lvl":1,"def":"plasament planificat"},{"k":"p","id":"x23","t":"specialist în protecția drepturilor copilului – persoană angajată de către autoritatea tutelară locală sau de către autoritatea tutelară teritorială, cu sau fără statut de funcționar public, care are studii în domeniul asistenței sociale, al psihologiei, al dreptului, al administrației publice sau în alte domenii conexe, care deține diplomă de studii superioare de licență sau de master, care activează în cadrul primăriei și desfășoară activități de suport pentru realizarea atribuțiilor autorității tutelare locale în domeniul protecției drepturilor copilului;","lvl":1,"def":"specialist în protecția drepturilor copilului"},{"k":"p","id":"x24","t":"responsabil legal al copilului – persoană sau autoritate, desemnată, conform legii, să exercite drepturi și obligații aferente creșterii, îngrijirii și educației copilului, prin acordarea suportului fizic, emoțional, educațional și de dezvoltare, în conformitate cu drepturile și interesele copilului;","lvl":1,"def":"responsabil legal al copilului"},{"k":"p","id":"x25","t":"copil aflat în conflict cu legea – copil care poate fi încadrat în una dintre următoarele situații:","lvl":1,"def":"copil aflat în conflict cu legea"},{"k":"lit","n":"a","id":"la","t":"copil care a săvârșit o faptă prevăzută de legislația penală sau contravențională, dar care, din cauza vârstei, nu este pasibil de răspundere penală și/sau de răspundere contravențională;","lvl":1},{"k":"lit","n":"b","id":"lb","t":"copil care a săvârșit o faptă care cade sub incidența legislației penale, copil liberat de răspundere penală sau de pedeapsă penală;","lvl":1},{"k":"lit","n":"c","id":"lc","t":"copil în privința căruia sunt aplicate măsuri de pedeapsă neprivative de libertate sau copil liberat condiționat de pedeapsă înainte de termen.","lvl":1}]},{"id":"4","num":"4","title":"Principiile protecţiei copilului aflat în situaţie de risc şi a copilului separat de părinţi","node":"n1","blocks":[{"k":"p","id":"x1","t":"Protecţia copilului se realizează conform următoarelor principii:","lvl":1},{"k":"lit","n":"a","id":"la","t":"asigurarea şi promovarea cu prioritate a interesului superior al copilului;","lvl":1},{"k":"lit","n":"b","id":"lb","t":"respectarea priorității privind creșterea și educarea copilului în familie;","lvl":1},{"k":"lit","n":"c","id":"lc","t":"dreptul prioritar al părinților de a-și educa copiii conform propriilor convingeri și responsabilitatea primară a părinților pentru creșterea, educarea și protecția copiilor lor;","lvl":1},{"k":"lit","n":"d","id":"ld","t":"obligația statului de a asigura familiei asistența necesară pentru creșterea și educarea copiilor;","lvl":1},{"k":"lit","n":"e","id":"le","t":"egalitatea șanselor și nediscriminarea;","lvl":1},{"k":"lit","n":"f","id":"lf","t":"cooperarea intersectorială și intervenția multidisciplinară;","lvl":1},{"k":"lit","n":"g","id":"lg","t":"asistența individualizată a fiecărui copil;","lvl":1},{"k":"lit","n":"h","id":"lh","t":"respectarea demnității copilului;","lvl":1},{"k":"lit","n":"i","id":"li","t":"asigurarea participării copilului la luarea deciziilor care îl privesc, ținând cont de vârsta și de gradul său de maturitate;","lvl":1},{"k":"lit","n":"j","id":"lj","t":"asigurarea continuității în creșterea și educarea copilului, ținând cont de identitatea sa etnică, religioasă, culturală și lingvistică, în cazul luării unei măsuri de protecție;","lvl":1},{"k":"lit","n":"k","id":"lk","t":"celeritate în luarea oricărei decizii cu privire la copil;","lvl":1},{"k":"lit","n":"l","id":"ll","t":"responsabilitatea autorităților pentru asigurarea protecției împotriva violenței, neglijării și exploatării copilului.","lvl":1}]},{"id":"5","num":"5","title":"Cadrul general de activitate al autorităţilor tutelare","node":"n1","blocks":[{"k":"al","n":"1","id":"a1","t":"Autorităţile tutelare trebuie să întreprindă toate măsurile necesare pentru asistenţa şi suportul copiilor şi al familiilor acestora în scopul prevenirii separării copilului de mediul familial sau, după caz, în scopul (re)integrării acestuia în familie.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Plasamentul copilului poate fi dispus de autorităţile tutelare numai în cazul în care, în urma evaluărilor, se constată că menţinerea copilului alături de părinţi nu este posibilă sau contravine interesului superior al acestuia.","lvl":1},{"k":"al","n":"3","id":"a3","t":"În cazul separării copilului de părinți din cauza aflării acestuia în situațiile de risc prevăzute la art. 8, autoritatea tutelară teritorială dispune plasamentul copilului, ținând cont de prioritatea plasării acestuia în serviciul tutelă/curatelă în cadrul familiei extinse sau în cadrul familiei persoanei cu care copilul a stabilit relații apropiate (vecin, prieten de familie etc.) față de celelalte tipuri de servicii de plasament, iar în cazul în care acest lucru este imposibil – de prioritatea plasării în servicii de plasament de tip familial față de plasarea în cele de tip rezidențial.","lvl":1,"r":[[102,108,{"art":"8"}]]}]},{"id":"6","num":"6","title":"Atribuţiile autorităţii tutelare locale","node":"n2","blocks":[{"k":"al","n":"1","id":"a1","t":"Autoritatea tutelară locală are următoarele atribuţii:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"asigură recepţionarea şi înregistrarea sesizărilor privind încălcarea drepturilor copilului, se autosesizează în cazul identificării unor copii aflați în situaţie de risc;","lvl":2},{"k":"lit","n":"a¹","id":"a1.la_1","t":"informează autoritatea tutelară teritorială despre cazurile copiilor care necesită asistență juridică calificată pentru respectarea drepturilor și intereselor acestora;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"coordonează examinarea sesizărilor privind încălcarea drepturilor copilului;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"în limita atribuţiilor sale și în cooperare cu autoritatea tutelară teritorială, întreprinde acţiunile necesare pentru prevenirea separării copilului de mediul familial sau pentru (re)integrarea copilului în familie;","lvl":2},{"k":"lit","n":"d","id":"a1.ld","t":"asigură evaluarea familiilor cu copii aflați în situație de risc și a copiilor separați de părinți;","lvl":2},{"k":"lit","n":"e","id":"a1.le","t":"asigură luarea copilului de la părinți sau de la persoanele în grija cărora se află acesta în cazul existenței unui pericol iminent pentru viața sau sănătatea lui și înaintează, în termen de 3 zile lucrătoare, acțiunea în instanța de judecată privind decăderea din drepturile părintești sau privind luarea copilului de la părinți fără ca aceștia să fie decăzuți din drepturile părintești;","lvl":2},{"k":"lit","n":"f","id":"a1.lf","t":"asigură plasamentul de urgență al copiilor separați de părinți;","lvl":2},{"k":"lit","n":"g","id":"a1.lg","t":"asigură instituirea custodiei asupra copiilor ai căror părinți/unicul părinte se află temporar în altă localitate din țară sau de peste hotare ori nu-și pot realiza obligațiile privind creșterea, îngrijirea și educația copilului din cauza problemelor de sănătate;","lvl":2},{"k":"lit","n":"h","id":"a1.lh","t":"asigură luarea și scoaterea de la evidență a familiilor cu copii aflați în situație de risc și a copiilor separați de părinți;","lvl":2},{"k":"lit","n":"i","id":"a1.li","t":"participă la procedura de luare a copilului de la părinţi;","lvl":2},{"k":"lit","n":"j","id":"a1.lj","t":"eliberează şi transmite autorităţii tutelare teritoriale avize privind plasamentul planificat al copiilor;","lvl":2},{"k":"lit","n":"k","id":"a1.lk","t":"cooperează, la nivel local, cu instituţiile, structurile şi serviciile cu atribuţii în domeniul protecţiei copilului;","lvl":2},{"k":"lit","n":"k¹","id":"a1.lk_1","t":"solicită, în caz de necesitate, oficiului teritorial al Consiliului Național de Asistență Juridică Garantată de Stat desemnarea unui avocat în vederea înaintării acțiunii în instanța de judecată privind decăderea din drepturile părintești sau privind luarea copilului de la părinți fără ca aceștia să fie decăzuți din drepturile părintești;","lvl":2},{"k":"lit","n":"l","id":"a1.ll","t":"coordonează procesul de monitorizare a situaţiei familiilor cu copii aflați în situaţie de risc şi a copiilor separaţi de părinţi;","lvl":2},{"k":"lit","n":"l¹","id":"a1.ll_1","t":"asigură monitorizarea situației copiilor ai căror părinți/unicul părinte se află temporar în altă localitate din țară sau de peste hotare;","lvl":2},{"k":"lit","n":"m","id":"a1.lm","t":"coordonează procesul de analiză a situaţiei la nivel local privind protecţia copiilor aflați în situaţie de risc şi a copiilor separaţi de părinţi;","lvl":2},{"k":"lit","n":"n","id":"a1.ln","t":"planifică şi decide realizarea măsurilor de informare a populaţiei privind drepturile copilului;","lvl":2},{"k":"lit","n":"o","id":"a1.lo","t":"în limita atribuţiilor sale, întreprinde măsurile necesare pentru respectarea drepturilor patrimoniale ale copiilor cu statut de copil rămas fără ocrotire părintească sau de copil rămas temporar fără ocrotire părintească;","lvl":2},{"k":"lit","n":"p","id":"a1.lp","t":"colaborează cu autoritățile tutelare teritoriale și centrale în vederea protecției copiilor aflați în situație de risc și a copiilor separați de părinți, inclusiv prin informarea reciprocă pe probleme de interes comun;","lvl":2},{"k":"lit","n":"q","id":"a1.lq","t":"expediază către autoritatea tutelară teritorială procesul-verbal întocmit în cazurile de identificare a copiilor străini care au intrat pe teritoriul Republicii Moldova fără a fi însoțiți de o persoană adultă responsabilă pentru ei prin lege sau care au fost lăsați pe teritoriul Republicii Moldova fără un act juridic, în termen de până la 24 de ore de la data întocmirii acestuia.","lvl":2},{"k":"note","t":"[Art.6 al.(1), lit.q) introdusă prin LP167 din 30.07.26, MO435-438/09.09.26 art. 452; în vigoare 09.12.26]","id":"n1","lvl":0},{"k":"al","n":"2","id":"a2","t":"Autoritatea tutelară locală își exercită atribuțiile direct sau prin intermediul specialistului pentru protecția drepturilor copilului.","lvl":1}]},{"id":"7","num":"7","title":"Atribuţiile autorităţii tutelare teritoriale","node":"n2","blocks":[{"k":"p","id":"x1","t":"Autoritatea tutelară teritorială are următoarele atribuţii:","lvl":1},{"k":"lit","n":"a","id":"la","t":"recepţionează, înregistrează şi transmite, conform competenţei, sesizările privind încălcarea drepturilor copilului;","lvl":1},{"k":"lit","n":"b","id":"lb","t":"în limita atribuţiilor, acordă sprijin autorităţilor tutelare locale în procesul de identificare, evaluare şi asistenţă a copiilor aflați în situaţie de risc şi a copiilor separaţi de părinţi şi participă la acest proces în caz de necesitate;","lvl":1},{"k":"lit","n":"c","id":"lc","t":"întreprinde, în colaborare cu autoritatea tutelară locală, acţiunile necesare privind prevenirea separării copilului de mediul familial sau privind (re)integrarea lui în familie;","lvl":1},{"k":"lit","n":"d","id":"ld","t":"asigură plasamentul planificat al copiilor separați de părinți;","lvl":1},{"k":"lit","n":"d¹","id":"ld_1","t":"asigură instituirea tutelei/curatelei asupra copiilor cu statut de copil rămas fără ocrotire părintească și de copil rămas temporar fără ocrotire părintească; asigură instituirea și convocarea consiliului de familie al copilului și desemnarea tutorelui/curatorului special și a celui supleant, în conformitate cu Codul civil;","lvl":1,"r":[[313,324,{"a":"cod:civil","whole":true}]]},{"k":"lit","n":"e","id":"le","t":"asigură stabilirea/retragerea statutului de copil rămas temporar fără ocrotire părintească sau de copil rămas fără ocrotire părintească;","lvl":1},{"k":"lit","n":"f","id":"lf","t":"asigură stabilirea statutului de copil adoptabil;","lvl":1},{"k":"lit","n":"g","id":"lg","t":"ţine evidenţa copiilor rămaşi temporar fără ocrotire părintească şi a copiilor rămaşi fără ocrotire părintească aflaţi în plasament planificat, recepţionează/sistematizează datele privind copiii aflaţi în evidenţa autorităţilor tutelare locale;","lvl":1},{"k":"lit","n":"h","id":"lh","t":"asigură reprezentarea intereselor şi a drepturilor copiilor în instanţa de judecată și în alte instituții sau autorități;","lvl":1},{"k":"lit","n":"h¹","id":"lh_1","t":"participă în calitate de reprezentant legal al copilului victimă sau martor al infracțiunii ori contravenției, precum și al copilului care are calitate de contravenient, bănuit, învinuit, inculpat – în cazul în care nu sunt prezenți părinții sau tutorele/curatorul copilului și în temeiul ordonanței organului de urmărire penală sau al încheierii instanței de judecată prin care autoritatea tutelară teritorială a fost desemnată ca reprezentant legal al copilului respectiv;","lvl":1},{"k":"lit","n":"h²","id":"lh_2","t":"solicită, în caz de necesitate, oficiului teritorial al Consiliului Național de Asistență Juridică Garantată de Stat desemnarea unui avocat care să reprezinte în raport cu organul de urmărire penală și/sau în instanța de judecată interesele copilului aflat în situație de risc față de care a fost dispus plasamentul de urgență sau plasamentul planificat;","lvl":1},{"k":"lit","n":"i","id":"li","t":"asigură, la nivel teritorial, cooperarea dintre instituţiile, structurile şi serviciile cu atribuţii în domeniul protecţiei copilului;","lvl":1},{"k":"lit","n":"j","id":"lj","t":"determină necesităţile de formare profesională a specialiştilor implicaţi în protecţia copilului în domeniul respectării drepturilor copilului și asigură formarea profesională inițială și cea continuă, în conformitate cu necesitățile identificate;","lvl":1},{"k":"lit","n":"k","id":"lk","t":"analizează anual datele privind situația copiilor din unitățile administrativ-teritoriale arondate și prezintă propuneri privind instituirea sau dezvoltarea serviciilor sociale în conformitate cu necesitățile identificate, după cum urmează:","lvl":1},{"k":"dash","id":"d1","t":"agențiile teritoriale de asistență socială – autorității centrale pentru protecția copilului;","lvl":2},{"k":"dash","id":"d2","t":"Direcția generală pentru protecția drepturilor copilului din Chișinău/Direcția principală a sănătății și protecției sociale din unitatea teritorială autonomă Găgăuzia – Consiliului municipal Chișinău/autorităților publice ale unității teritoriale autonome Găgăuzia și/sau autorității centrale pentru protecția copilului, după caz;","lvl":2},{"k":"lit","n":"l","id":"ll","t":"întreprinde măsuri de informare a populaţiei privind drepturile copilului;","lvl":1},{"k":"lit","n":"m","id":"lm","t":"colaborează cu autoritățile tutelare locale, teritoriale și centrale în vederea protecției copiilor aflați în situație de risc și a copiilor separați de părinți, inclusiv prin informarea reciprocă pe probleme de interes comun;","lvl":1},{"k":"lit","n":"n","id":"ln","t":"asigură stabilirea şi plata indemnizaţiilor pentru copiii adoptaţi şi cei aflaţi sub tutelă/curatelă, precum și a indemnizațiilor zilnice pentru copiii cu statut de copil rămas temporar fără ocrotire părintească și cu statut de copil rămas fără ocrotire părintească, din contul bugetului de stat; în cazul municipiului Chișinău și al unității teritoriale autonome Găgăuzia, finanțarea se face prin transferuri cu destinație specială către bugetele acestora;","lvl":1},{"k":"lit","n":"o","id":"lo","t":"în cooperare cu autorităţile tutelare locale, cu alte autorităţi şi instituţii care activează în domeniile asistenţei sociale, educaţiei, ocrotirii sănătăţii, precum şi cu organele de drept, întreprinde măsurile necesare pentru asigurarea implementării prevederilor Convenţiei asupra aspectelor civile ale răpirii internaţionale de copii, adoptată la Haga la 25 octombrie 1980, și celor ale Convenției europene asupra recunoașterii și executării deciziilor privind supravegherea copiilor și restabilirea supravegherii copiilor, adoptată la Luxemburg la 20 mai 1980;","lvl":1},{"k":"lit","n":"p","id":"lp","t":"în cooperare cu alte autorități, inclusiv autorități tutelare locale, întreprinde măsurile necesare pentru protecția și repatrierea copiilor neînsoțiți identificați peste hotare și a celor aflați în dificultate peste hotare, în conformitate cu procedurile stabilite de către Guvern;","lvl":1},{"k":"lit","n":"q","id":"lq","t":"în cazul existenței unui pericol iminent pentru viața sau sănătatea copilului, exercită de urgență atribuțiile prevăzute la art. 6 alin. (1) lit. d)–f) dacă autoritatea tutelară locală competentă se află într-o imposibilitate obiectivă și documentată de a interveni ori refuză nejustificat să își exercite atribuțiile. Situația se constată prin act motivat al autorității tutelare teritoriale, iar procurorul este informat în termen de cel mult 24 de ore;","lvl":1,"r":[[124,151,{"art":"6","al":"1","lit":"d","lit2":"f"}]]},{"k":"note","t":"[Art.7 lit.q) introdusă prin LP167 din 30.07.26, MO435-438/09.09.26 art. 452; în vigoare 09.12.26]","id":"n1","lvl":0},{"k":"lit","n":"r","id":"lr","t":"în termen de cel mult 3 zile lucrătoare de la data emiterii dispoziției autorității tutelare cu privire la plasamentul/încetarea plasamentului copilului, prezintă casei teritoriale de asigurări sociale informația privind plasarea copilului, în condițiile art. 12, într-un serviciu de plasament sau privind încetarea plasamentului copilului în serviciul de plasament, în scopul stabilirii/modificării/suspendării sau încetării achitării oricărui tip de prestații sociale de către organele de asigurări sociale.","lvl":1,"r":[[255,262,{"art":"12"}]]},{"k":"note","t":"[Art.7 lit.r) introdusă prin LP167 din 30.07.26, MO435-438/09.09.26 art. 452; în vigoare 09.12.26]","id":"n2","lvl":0}]},{"id":"7_1","num":"7¹","title":"Atribuțiile autorității centrale pentru protecția copilului","node":"n2","blocks":[{"k":"p","id":"x1","t":"Autoritatea centrală pentru protecția copilului exercită următoarele atribuții:","lvl":1},{"k":"lit","n":"a","id":"la","t":"elaborează proiecte de acte normative pentru perfecționarea legislației în domeniul protecției sociale a familiei și protecției drepturilor copilului și monitorizează implementarea acesteia;","lvl":1},{"k":"lit","n":"b","id":"lb","t":"exercită atribuțiile de autoritate centrală desemnată în contextul implementării prevederilor Convenției asupra protecției copiilor și cooperării în materie de adopție internațională, încheiată la Haga la 29 mai 1993, celor ale Convenției asupra aspectelor civile ale răpirii internaționale de copii, întocmită la Haga la 25 octombrie 1980, și celor ale Convenției europene asupra recunoașterii și executării deciziilor privind supravegherea copiilor și restabilirea supravegherii copiilor, adoptată la Luxemburg la 20 mai 1980;","lvl":1},{"k":"lit","n":"c","id":"lc","t":"analizează politicile de protecție socială a familiei și de protecție a drepturilor copilului și elaborează propuneri și recomandări privind îmbunătățirea situației în domeniu;","lvl":1},{"k":"lit","n":"d","id":"ld","t":"elaborează și monitorizează aplicarea standardelor minime de calitate pentru tipurile de servicii sociale prestate copiilor/familiilor cu copii în scopul prevenirii, limitării sau depășirii unei situații de dificultate;","lvl":1},{"k":"lit","n":"e","id":"le","t":"asigură dezvoltarea mecanismelor de protecție socială a copiilor/familiilor cu copii, asigură accesul copiilor și al familiilor la servicii sociale de calitate;","lvl":1},{"k":"lit","n":"f","id":"lf","t":"susține metodologic dezvoltarea acțiunilor comunitare privind prevenirea separării copilului de familie și menținerea lui în mediul familial;","lvl":1},{"k":"lit","n":"g","id":"lg","t":"coordonează metodologic activitatea autorităților tutelare din cadrul unităților administrativ-teritoriale de nivelul întâi și nivelul al doilea;","lvl":1},{"k":"lit","n":"h","id":"lh","t":"coordonează și monitorizează activitatea în domeniul adopției;","lvl":1},{"k":"lit","n":"i","id":"li","t":"asigură accesul persoanelor fizice și juridice, autorizate prin lege, la informația privind copiii luați în evidență pentru adopție;","lvl":1},{"k":"lit","n":"j","id":"lj","t":"colectează, analizează și asigură protecția și confidențialitatea datelor privind copiii aflați în situație de risc și copiii separați de părinți, privind adopțiile naționale și cele internaționale;","lvl":1},{"k":"lit","n":"k","id":"lk","t":"colectează și analizează datele cu privire la serviciile sociale prestate familiilor cu copii și copiilor separați de părinți;","lvl":1},{"k":"lit","n":"l","id":"ll","t":"monitorizează respectarea drepturilor copilului în perioada preadopție şi cea postadopție;","lvl":1},{"k":"lit","n":"m","id":"lm","t":"coordonează elaborarea, aprobă și monitorizează implementarea programelor de găzduire peste hotare a copiilor adoptabili în vederea adopției;","lvl":1},{"k":"lit","n":"n","id":"ln","t":"ține Registrul de stat al adopției și Registrul de stat al copiilor aflați în situație de risc și al copiilor separați de părinți, în condițiile legii;","lvl":1},{"k":"lit","n":"o","id":"lo","t":"asigură, în comun cu Ministerul Afacerilor Externe și Integrării Europene, protecția și repatrierea copiilor neînsoțiți identificați peste hotare și a celor aflați în dificultate peste hotare;","lvl":1},{"k":"lit","n":"p","id":"lp","t":"promovează măsuri de prevenire a violenței împotriva copilului;","lvl":1},{"k":"lit","n":"q","id":"lq","t":"coordonează implementarea mecanismului de cooperare intersectorială pentru identificarea, evaluarea, referirea, asistența și monitorizarea copiilor victime și potențiale victime ale violenței, neglijării, exploatării și traficului, precum și a mecanismului de cooperare intersectorială pentru prevenirea primară a riscurilor privind bunăstarea copilului;","lvl":1},{"k":"lit","n":"r","id":"lr","t":"coordonează, în comun cu autoritățile publice centrale și cele locale, cu organismele internaționale și organizațiile societății civile, realizarea programelor de protecție socială a familiei și de protecție a drepturilor copilului;","lvl":1},{"k":"lit","n":"s","id":"ls","t":"coordonează/participă la realizarea studiilor în domeniul protecției drepturilor copilului;","lvl":1},{"k":"lit","n":"t","id":"lt","t":"acordă suport metodologic agențiilor teritoriale de asistență socială, structurilor teritoriale de asistență socială, Direcției generale pentru protecția drepturilor copilului Chișinău, Direcției principale a sănătății și protecției sociale din unitatea teritorială autonomă Găgăuzia, autorității tutelare locale și organizațiilor societății civile prestatoare de servicii în domeniu;","lvl":1},{"k":"lit","n":"u","id":"lu","t":"elaborează rapoarte naționale periodice privind aplicarea la nivel național a Convenției cu privire la drepturile copilului, adoptată de Adunarea Generală a Organizației Națiunilor Unite la 20 noiembrie 1989.","lvl":1}]},{"id":"8","num":"8","title":"Identificarea copiilor aflați în situaţie de risc","node":"n3","blocks":[{"k":"p","id":"x1","t":"Autoritatea tutelară locală este obligată să se autosesizeze şi/sau să asigure recepţionarea şi înregistrarea sesizărilor cu privire la copiii aflaţi în următoarele situaţii:","lvl":1},{"k":"lit","n":"a","id":"la","t":"copiii sunt supuși violenței;","lvl":1},{"k":"lit","n":"b","id":"lb","t":"copiii sunt neglijaţi;","lvl":1},{"k":"lit","n":"c","id":"lc","t":"copiii practică vagabondajul, cerşitul, prostituţia;","lvl":1},{"k":"lit","n":"d","id":"ld","t":"copiii sunt lipsiţi de îngrijire şi supraveghere din partea părinţilor din cauza absenţei acestora de la domiciliu din motive necunoscute;","lvl":1},{"k":"lit","n":"e","id":"le","t":"părinţii copiilor au decedat;","lvl":1},{"k":"lit","n":"f","id":"lf","t":"copiii trăiesc în stradă, au fugit ori au fost alungaţi de acasă;","lvl":1},{"k":"lit","n":"g","id":"lg","t":"părinţii copiilor refuză să-şi exercite obligaţiile părinteşti privind creşterea şi îngrijirea copilului;","lvl":1},{"k":"lit","n":"h","id":"lh","t":"copiii au fost abandonaţi de părinţi;","lvl":1},{"k":"lit","n":"i","id":"li","t":"în privința unuia dintre părinții copilului este instituită o măsură de ocrotire judiciară (ocrotire provizorie, curatelă sau tutelă);","lvl":1},{"k":"lit","n":"j","id":"lj","t":"copiii sunt victime ale infracţiunilor, dacă se află în una sau mai multe situații indicate la lit. a)–i);","lvl":1,"r":[[95,105,{"lit":"a","lit2":"i","art":"8"}]]},{"k":"lit","n":"k","id":"lk","t":"copiii sunt expuși riscului de a comite infracțiuni sau se află în conflict cu legea;","lvl":1},{"k":"lit","n":"l","id":"ll","t":"copiii străini sau apatrizi au intrat pe teritoriul Republicii Moldova fără a fi însoțiți de o persoană adultă care să fie responsabilă pentru ei prin lege sau au fost lăsați pe teritoriul Republicii Moldova fără un act juridic.","lvl":1}]},{"id":"9","num":"9","title":"Evaluarea situaţiei copilului, evidenţa şi asistenţa copiilor aflați în situaţie de risc","node":"n3","blocks":[{"k":"al","n":"1","id":"a1","t":"Autoritatea tutelară locală în a cărei rază este locul aflării copilului dispune evaluarea iniţială a situaţiei copilului de către specialistul pentru protecția drepturilor copilului, iar în lipsa acestuia – de către asistentul social comunitar, cu implicarea în procesul de evaluare, după caz, a altor specialişti din domeniul ocrotirii sănătăţii, educaţiei, ordinii publice etc.:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"în termen de 24 de ore – în cazul primirii informaţiilor prevăzute la art. 8 lit. a)–c);","lvl":2,"r":[[70,87,{"art":"8","lit":"a","lit2":"c"}]]},{"k":"lit","n":"b","id":"a1.lb","t":"imediat – în cazul în care din conţinutul sesizării se constată existenţa unui pericol iminent pentru copil, precum şi în cazul primirii informaţiilor prevăzute la art. 8 lit. d)–i) sau lit. l).","lvl":2,"r":[[164,181,{"art":"8","lit":"d","lit2":"i"}],[186,193,{"lit":"l","art":"9","al":"1"}]]},{"k":"al","n":"2","id":"a2","t":"În cazul în care situaţiile de risc prevăzute la art. 8 lit. a), b) sau h) s-au produs în afara familiei, măsurile specificate la alin.(1) se întreprind cu acordul prealabil al părinţilor/reprezentantului legal al copilului, cu excepţia cazurilor în care dezacordul acestora contravine interesului superior al copilului.","lvl":1,"r":[[49,63,{"art":"8","lit":"a"}],[65,67,{"art":"8","lit":"b"}],[72,74,{"art":"8","lit":"h"}],[130,138,{"al":"1","art":"9"}]]},{"k":"al","n":"3","id":"a3","t":"În cazul în care situaţiile de risc prevăzute la art. 8 lit. a)–c) s-au produs într-un serviciu de plasament, autoritatea tutelară locală în a cărei rază este locul aflării copilului întreprinde măsurile prevăzute la alin. (1), asigurând securitatea pentru viaţa şi sănătatea copilului, şi informează imediat autoritatea tutelară teritorială care va decide asupra măsurilor de protecţie a copilului.","lvl":1,"r":[[49,66,{"art":"8","lit":"a","lit2":"c"}],[217,226,{"al":"1","art":"9"}]]},{"k":"al","n":"4","id":"a4","t":"Dacă în urma evaluării iniţiale a situației copilului se confirmă situaţia de risc pentru copil, autoritatea tutelară locală dispune imediat luarea în evidenţă a copilului aflat în situaţie de risc.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Registrul de evidenţă a copiilor aflați în situaţii de risc se ţine de către autoritatea tutelară locală, fiind completat de către specialistul pentru protecția drepturilor copilului, iar în lipsa acestuia – de către asistentul social comunitar.","lvl":1},{"k":"al","n":"6","id":"a6","t":"Evaluarea, asistenţa şi monitorizarea copilului aflat în situaţie de risc se realizează prin utilizarea metodei managementului de caz, aprobată de autoritatea centrală pentru protecţia copilului.","lvl":1},{"k":"al","n":"7","id":"a7","t":"În cazul recepţionării informaţiei despre copiii aflaţi în situaţia de risc prevăzută la art. 8 lit. h), autoritatea tutelară locală sau specialistul pentru protecția drepturilor copilului participă la întocmirea actului de abandon al copilului într-o instituţie sau a procesului-verbal privind găsirea copilului.","lvl":1,"r":[[89,103,{"art":"8","lit":"h"}]]},{"k":"al","n":"8","id":"a8","t":"În cazul în care locul aflării copilului este altul decât domiciliul părinţilor, autoritatea tutelară locală sesizează autoritatea tutelară teritorială în a cărei rază domiciliază părinţii în scopul prezentării datelor necesare pentru realizarea evaluării iniţiale şi complexe a situaţiei copilului.","lvl":1}]},{"id":"10","num":"10","title":"Luarea copilului de la părinți sau de la persoanele în grija cărora acesta se află","node":"n3","blocks":[{"k":"al","n":"1","id":"a1","t":"În cazul în care, ca urmare a evaluării iniţiale, se constată existenţa unui pericol iminent pentru viaţa sau sănătatea copilului, autoritatea tutelară în a cărei rază este locul aflării acestuia dispune imediat luarea copilului de la părinţi sau de la persoanele în grija cărora acesta se află, comunicând acest fapt procurorului în termen de cel mult 24 de ore.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Procedura de luare a copilului de la părinţi sau de la persoanele în grija cărora acesta se află se efectuează cu participarea obligatorie a autorității tutelare locale sau a reprezentantului acesteia, a specialistului pentru protecția drepturilor copilului, a asistentului social comunitar, a medicului/asistentului medicului de familie și a ofițerului de sector al poliției.","lvl":1},{"k":"al","n":"3","id":"a3","t":"În cazul prevăzut la alin. (1), autoritatea tutelară locală, în termen de 3 zile lucrătoare, va porni o acţiune în instanţa de judecată privind decăderea din drepturile părintești sau privind luarea copilului de la părinţi fără ca aceștia să fie decăzuți din drepturile părintești. Dacă această cerință nu este îndeplinită, copilul va fi înapoiat imediat părinţilor.","lvl":1,"r":[[21,30,{"al":"1","art":"10"}]]},{"k":"al","n":"4","id":"a4","t":"Cu excepția situației prevăzute la alin. (1), luarea copilului de la părinți se efectuează numai în baza unei hotărâri a instanței de judecată privind decăderea din drepturile părintești sau a unei hotărâri a instanței de judecată privind luarea copilului fără ca părinții să fie decăzuți din drepturile părintești conform prevederilor art. 67–69, 71 și 72 din Codul familiei.","lvl":1,"r":[[35,44,{"al":"1","art":"10"}],[336,346,{"art":"67","art2":"69","a":"cod:familiei"}],[348,350,{"art":"71","a":"cod:familiei"}],[354,356,{"art":"72","a":"cod:familiei"}],[361,375,{"a":"cod:familiei","whole":true}]]}]},{"id":"11","num":"11","title":"Plasamentul de urgenţă","node":"n4","blocks":[{"k":"al","n":"1","id":"a1","t":"Autoritatea tutelară locală emite dispoziţia privind plasamentul de urgenţă al copilului și informează în acest sens autoritatea tutelară teritorială în a cărei rază este locul de plasament al copilului în cazul luării copilului de la părinți în condițiile art. 10 alin. (1) sau în cazul lipsei părinților în momentul identificării copilului în situaţiile specificate la art. 8 lit. d)–h) sau lit. l).","lvl":1,"r":[[257,274,{"art":"10","al":"1"}],[371,388,{"art":"8","lit":"d","lit2":"h"}],[393,400,{"lit":"l","art":"11","al":"1"}]]},{"k":"al","n":"2","id":"a2","t":"Ținând cont de interesul superior al copilului, acesta poate fi plasat de urgenţă în:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"familia rudelor sau a altor persoane cu care a stabilit relaţii apropiate (vecini, prieteni de familie etc.) și care doresc să primească/să ţină copilul pentru a-l creşte şi educa în familia lor, în baza cererii scrise a acestora, pornind de la necesitatea asigurării stabilităţii şi continuităţii în îngrijirea, creşterea şi educația copilului, ținând cont de identitatea sa etnică, religioasă, culturală şi lingvistică;","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"servicii de plasament de tip familial (casă de copii de tip familial, asistență parentală profesionistă);","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"servicii de plasament de tip rezidenţial.","lvl":2},{"k":"al","n":"3","id":"a3","t":"Copilul separat de părinţi poate fi plasat de urgenţă pe un termen de până la 72 de ore, cu posibilitatea prelungirii termenului de plasament până la 45 de zile lucrătoare, perioadă în care se efectuează evaluarea complexă a situaţiei copilului și se emite dispoziția cu privire la (re)integrarea copilului în familie sau cu privire la plasamentul planificat al acestuia.","lvl":1},{"k":"note","t":"[Art.11 al.(3) modificat prin LP167 din 30.07.26, MO435-438/09.09.26 art. 452; în vigoare 09.12.26]","id":"n1","lvl":0}]},{"id":"12","num":"12","title":"Plasamentul planificat","node":"n4","blocks":[{"k":"al","n":"1","id":"a1","t":"Plasamentul planificat al copilului se efectuează conform dispoziţiei autorităţii tutelare teritoriale, cu avizul autorităţii tutelare locale şi numai în baza avizului pozitiv al Comisiei pentru protecţia copilului aflat în dificultate, modul de organizare și funcționare a căreia este aprobat de Guvern.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Copiii pot fi plasați în:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"- abrogată;","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"serviciul de plasament de tip familial (tutelă/curatelă, casă de copii de tip familial, asistenţă parentală profesionistă și alte servicii stabilite în modul corespunzător de Guvern);","lvl":2},{"k":"note","t":"[Art.12 al.(2), lit.b) modificată prin LP167 din 30.07.26, MO435-438/09.09.26 art. 452; în vigoare 09.12.26]","id":"n1","lvl":0},{"k":"lit","n":"c","id":"a2.lc","t":"serviciul de plasament de tip rezidenţial (casă comunitară, centru de plasament temporar, alt tip de serviciu).","lvl":2},{"k":"al","n":"3","id":"a3","t":"La plasarea copilului în serviciul tutelă/curatelă, autoritatea tutelară teritorială ține cont de prioritatea plasării copilului:","lvl":1},{"k":"lit","n":"a","id":"a3.la","t":"în familia extinsă;","lvl":2},{"k":"lit","n":"b","id":"a3.lb","t":"în familia persoanei cu care copilul a stabilit relații apropiate (vecin, prieten de familie etc.);","lvl":2},{"k":"lit","n":"c","id":"a3.lc","t":"în familia adoptatorului, conform prevederilor alin. (4).","lvl":2,"r":[[47,56,{"al":"4","art":"12"}]]},{"k":"al","n":"4","id":"a4","t":"În cazul copilului cu statut de copil rămas temporar fără ocrotire părintească sau de copil rămas fără ocrotire părintească, autoritatea tutelară teritorială de la domiciliul copilului poate propune Comisiei pentru protecția copilului aflat în dificultate examinarea avizării pozitive a plasării copilului în serviciul tutelă/curatelă în cadrul familiei unui adoptator, selectat conform metodologiei aprobate de către autoritatea centrală pentru protecția copilului.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Plasamentul planificat al copilului în serviciile indicate la alin. (2) încetează odată cu atingerea de către acesta a vârstei de 18 ani.","lvl":1,"r":[[62,71,{"al":"2","art":"12"}]]},{"k":"note","t":"[Art.12 al.(5) în redacția LP167 din 30.07.26, MO435-438/09.09.26 art. 452; în vigoare 09.12.26]","id":"n2","lvl":0}]},{"id":"12_1","num":"12¹","title":"Plasamentul copilului al cărui părinte este minor","node":"n4","blocks":[{"k":"al","n":"1","id":"a1","t":"Copilul al cărui părinte este minor beneficiază de serviciile prestate în cadrul serviciilor de plasament fără avizul Comisiei pentru protecţia copilului aflat în dificultate și fără dispoziția autorității tutelare teritoriale privind stabilirea statutului de copil rămas temporar fără ocrotire părintească sau de copil rămas fără ocrotire părintească ori privind plasamentul de urgență sau al celui planificat al copilului respectiv.","lvl":1},{"k":"al","n":"2","id":"a2","t":"În cazul copilului al cărui părinte este minor, autoritatea tutelară teritorială emite o dispoziție suplimentară cu privire la plasamentul copilului respectiv împreună cu părintele minor:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"concomitent cu plasamentul părintelui minor;","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"după nașterea copilului al cărui părinte este un minor aflat în plasament;","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"în cazul plasamentului copilului al cărui părinte este minor – după dispunerea plasamentului părintelui minor.","lvl":2},{"k":"al","n":"3","id":"a3","t":"Copilul al cărui părinte este minor beneficiază de prestații sociale, în conformitate cu legislația, de la data plasării în serviciu de plasament și în temeiul dispoziției cu privire la plasamentul copilului împreună cu părintele minor.","lvl":1},{"k":"al","n":"4","id":"a4","t":"În cazul în care după plasament, menținerea copilului împreună cu părintele minor nu este posibilă sau contravine interesului superior al copilului, autoritatea tutelară teritorială întreprinde măsurile necesare pentru stabilirea statutului copilului al cărui părinte este minor și asigură un nou plasament al acestuia conform prevederilor legislației.","lvl":1}]},{"id":"12_2","num":"12²","title":"Pregătirea pentru viața independentă","node":"n4","blocks":[{"k":"p","id":"x1","t":"Pentru copiii cu statut de copil rămas temporar fără ocrotire părintească sau de copil rămas fără ocrotire părintească, începând cu atingerea vârstei de 16 ani, autoritatea tutelară teritorială în colaborare cu prestatorul și personalul serviciului în care este plasat copilul asigură pregătirea acestuia pentru viața independentă.","lvl":1}]},{"id":"12_3","num":"12³","title":"Organizarea și funcționarea serviciilor de asistență și protecție a copiilor aflați în situație de risc și a copiilor separați de părinți","node":"n4","blocks":[{"k":"p","id":"x1","t":"Modul de organizare și funcționare a serviciilor de asistență și protecție a copiilor aflați în situație de risc și a copiilor separați de părinți este stabilit de către Guvern.","lvl":1}]},{"id":"12_4","num":"12⁴","title":"Reprezentantul legal și responsabilul legal ai copilului separat de părinți","node":"n4","blocks":[{"k":"al","n":"1","id":"a1","t":"Exercitarea atribuțiilor de reprezentant legal al copiilor cu statut de copil rămas temporar fără ocrotire părintească sau de copil rămas fără ocrotire părintească este asigurată de către autoritatea tutelară teritorială, cu excepția copiilor plasați în serviciul tutelă/curatelă, pentru care reprezentantul legal este tutorele/curatorul.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Responsabilul legal al copilului pentru copiii menționați la alin. (1) este:","lvl":1,"r":[[61,70,{"al":"1","art":"12_4"}]]},{"k":"lit","n":"a","id":"a2.la","t":"tutorele/curatorul, asistentul parental profesionist ori părintele-educator – în cazul copiilor aflați în servicii de plasament de tip familial;","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"administrația serviciilor de plasament de tip rezidențial – în cazul copiilor aflați în serviciile respective;","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"custodele – în cazul copiilor asupra cărora este instituită custodia;","lvl":2},{"k":"lit","n":"d","id":"a2.ld","t":"adoptatorul – odată cu încredințarea copilului în familia acestuia, în condițiile art. 29 din Legea nr. 99/2010 privind regimul juridic al adopției, și până la revocarea încredințării sau până la devenirea irevocabilă a hotărârii instanței de judecată privind încuviințarea adopției.","lvl":2,"r":[[82,89,{"art":"29","a":"lege:99/2010"}],[94,111,{"a":"lege:99/2010","whole":true}]]},{"k":"note","t":"[Art.12⁴ al.(2), lit.d) introdusă prin LP167 din 30.07.26, MO435-438/09.09.26 art. 452; în vigoare 09.12.26]","id":"n1","lvl":0}]},{"id":"13","num":"13","title":"Custodia copiilor ai căror părinți/unicul părinte se află temporar în altă localitate din țară sau de peste hotare","node":"n4","blocks":[{"k":"al","n":"1","id":"a1","t":"În cazul copilului separat de părinți din cauza aflării temporare a părinților/unicului părinte pentru o perioadă mai mare de două luni în altă localitate din țară sau de peste hotare, autoritatea tutelară locală instituie custodia asupra acestuia, ca formă de protecție temporară a copilului, în scopul asigurării creșterii, îngrijirii și educației adecvate a acestuia.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Părinții/unicul părinte care intenționează să plece temporar în altă localitate din țară sau de peste hotare (la muncă, studii, tratament sau din alte motive) sunt obligați să depună la autoritatea tutelară locală de la locul de trai al persoanei/persoanelor care urmează să exercite custodia cererea privind instituirea custodiei asupra copilului și declarația privind acordul persoanei/persoanelor respective, conform modelului aprobat de către Guvern.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Prevederile alin. (2) se aplică și pentru părinții/unicul părinte care se află mai mult de două luni în altă localitate din țară sau de peste hotare, urmând ca aceștia să depună documentele indicate la alin. (2) sau să le transmită autorității tutelare locale:","lvl":1,"r":[[12,21,{"al":"2","art":"13"}],[202,211,{"al":"2","art":"13"}]]},{"k":"lit","n":"a","id":"a3.la","t":"prin scrisoare recomandată, adresată autorității tutelare locale;","lvl":2},{"k":"lit","n":"b","id":"a3.lb","t":"prin mesaj electronic pe adresa electronică oficială a autorității tutelare locale, cu denumirea mesajului „Confidențial. Articolul 13/140/2013”;","lvl":2,"r":[[122,134,{"art":"13"}]]},{"k":"lit","n":"c","id":"a3.lc","t":"prin intermediul persoanei în grija căreia se află copilul sau prin intermediul altor persoane.","lvl":2},{"k":"al","n":"4","id":"a4","t":"Prevederile prezentului articol se aplică și pentru tutorii/curatorii care se află temporar ori care intenționează să plece temporar în altă localitate din țară sau de peste hotare pentru o perioadă mai mare de două luni.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Documentele indicate la alin. (2) se depun/se transmit separat pentru fiecare copil, fiind semnate de părinți/unicul părinte sau de tutore/curator.","lvl":1,"r":[[24,33,{"al":"2","art":"13"}]]},{"k":"al","n":"6","id":"a6","t":"În cazul în care părinții au opinii diferite cu privire la persoana în grija căreia se va afla copilul, acestea sunt examinate de către autoritatea tutelară teritorială de la locul de trai al copilului, iar decizia autorității tutelare teritoriale poate fi contestată în instanța de judecată, care se pronunță cu privire la persoana în grija căreia se va afla copilul.","lvl":1},{"k":"al","n":"7","id":"a7","t":"Identificarea copiilor ai căror părinți/unicul părinte sau tutore/curator se află temporar în altă localitate din țară sau de peste hotare se efectuează de:","lvl":1},{"k":"lit","n":"a","id":"a7.la","t":"conducerea instituțiilor de învățământ– în cazul copiilor care frecventează astfel de instituții;","lvl":2},{"k":"lit","n":"b","id":"a7.lb","t":"specialistul în protecția drepturilor copilului, asistentul social comunitar, medicul de familie/asistentul medicului de familie sau ofițerul de sector al poliției – în cazul copiilor care nu frecventează instituții de învățământ.","lvl":2},{"k":"al","n":"8","id":"a8","t":"Informația cu privire la copiii ai căror părinți/unicul părinte sau tutore/curator se află temporar în altă localitate din țară sau de peste hotare se prezintă autorității tutelare locale:","lvl":1},{"k":"lit","n":"a","id":"a8.la","t":"semestrial, până la data de 30 aprilie și, respectiv, 30 octombrie – în situațiile indicate la alin. (7) lit. a);","lvl":2,"r":[[95,112,{"al":"7","lit":"a","art":"13"}]]},{"k":"lit","n":"b","id":"a8.lb","t":"în termen de 3 zile lucrătoare – în situațiile indicate la alin. (7) lit. b).","lvl":2,"r":[[59,76,{"al":"7","lit":"b","art":"13"}]]},{"k":"al","n":"9","id":"a9","t":"În cazul identificării copiilor ai căror părinți/unicul părinte sau tutore/curator se află temporar în altă localitate din țară sau de peste hotare asupra cărora nu este instituită custodia, autoritatea tutelară locală de la locul aflării copiilor respectivi întreprinde acțiunile necesare pentru informarea părinților, persoanei în grija căreia se află copilul și, după caz, autorității tutelare locale de la locul de trai al părinților despre obligația instituirii custodiei.","lvl":1},{"k":"al","n":"10","id":"a10","t":"După identificarea copiilor aflați în situațiile indicate la alin. (7) lit. b), în scopul constatării condițiilor de creștere, îngrijire și educație a acestora, autoritatea tutelară locală dispune evaluarea situației copiilor respectivi, în termen de 30 de zile lucrătoare, de către specialistul în protecția drepturilor copilului sau, în lipsa acestuia, de către asistentul social comunitar.","lvl":1,"r":[[61,78,{"al":"7","lit":"b","art":"13"}]]}]},{"id":"13_1","num":"13¹","title":"Instituirea custodiei asupra copiilor ai căror părinți/unicul părinte sau tutore/curator se află temporar în altă localitate din țară sau de peste hotare","node":"n4","blocks":[{"k":"al","n":"1","id":"a1","t":"După recepționarea documentelor indicate la art. 13 alin. (2), autoritatea tutelară locală întocmește un dosar pentru copil și, în termen de 3 zile lucrătoare, dispune evaluarea de către specialistul în protecția drepturilor copilului sau, în lipsa acestuia, de către asistentul social comunitar a situației copilului a condițiilor de creștere, îngrijire și educație, precum și a mediului familial al persoanei/persoanelor în grija cărora se va afla copilul, cu formularea concluziilor privind oportunitatea instituirii custodiei asupra copilului.","lvl":1,"r":[[44,61,{"art":"13","al":"2"}]]},{"k":"al","n":"2","id":"a2","t":"În baza dispoziției autorității tutelare locale, specialistul în protecția drepturilor copilului sau, în lipsa acestuia, asistentul social comunitar, în termen de 5 zile lucrătoare, prezintă acesteia evaluările indicate la alin. (1).","lvl":1,"r":[[223,232,{"al":"1","art":"13_1"}]]},{"k":"al","n":"3","id":"a3","t":"În temeiul evaluărilor, autoritatea tutelară locală, în termen de 3 zile lucrătoare, emite dispoziția privind instituirea sau privind refuzul instituirii custodiei asupra copilului. Un exemplar al dispoziției se anexează la dosarul copilului și câte un exemplar se transmite persoanei/persoanelor care au depus cererea privind instituirea custodiei și persoanei/persoanelor care și-au exprimat acordul să exercite atribuții de custode.","lvl":1},{"k":"al","n":"4","id":"a4","t":"În cazul refuzului autorității tutelare locale de a institui custodia, persoanele interesate pot contesta dispoziția respectivă în instanța de judecată conform legislației.","lvl":1}]},{"id":"13_2","num":"13²","title":"Persoanele care pot exercita atribuții de custode","node":"n4","blocks":[{"k":"al","n":"1","id":"a1","t":"Poate exercita atribuții de custode o persoană fizică sau un cuplu căsătorit (soț și soție), dacă și-au exprimat acordul și nu se află sub nicio restricție prevăzută de alin. (2).","lvl":1,"r":[[169,178,{"al":"2","art":"13_2"}]]},{"k":"al","n":"2","id":"a2","t":"Nu poate exercita atribuții de custode/responsabil legal al copilului:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"persoana care nu a împlinit 18 ani;","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"persoana în privința căreia a fost instituită o măsură de ocrotire judiciară;","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"persoana decăzută din drepturi părintești;","lvl":2},{"k":"lit","n":"d","id":"a2.ld","t":"persoana căreia, din cauza exercitării necorespunzătoare a atribuțiilor de tutore, curator sau custode, i s-a revocat tutela, curatela sau custodia;","lvl":2},{"k":"lit","n":"e","id":"a2.le","t":"persoana aflată în conflict de interese cu copilul respectiv;","lvl":2},{"k":"lit","n":"f","id":"a2.lf","t":"persoana care a prezentat documente sau informații false pentru instituirea custodiei;","lvl":2},{"k":"lit","n":"g","id":"a2.lg","t":"persoana care a fost condamnată pentru săvârșirea cu intenție a infracțiunilor contra vieții și sănătății persoanei, infracțiunilor contra libertății, cinstei și demnității persoanei, infracțiunilor privind viața sexuală, infracțiunilor contra familiei și minorilor.","lvl":2}]},{"id":"13_3","num":"13³","title":"Drepturile și obligațiile custodelui","node":"n4","blocks":[{"k":"al","n":"1","id":"a1","t":"Custodia este o sarcină personală și gratuită.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Custodele are următoarele drepturi:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"să fie informat despre istoricul și starea sănătății copilului;","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"să beneficieze de asistență și suport din partea autorităților tutelare;","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"să solicite încetarea custodiei.","lvl":2},{"k":"al","n":"3","id":"a3","t":"Custodele are următoarele obligații:","lvl":1},{"k":"lit","n":"a","id":"a3.la","t":"să asigure copilului îngrijire și educație individualizată;","lvl":2},{"k":"lit","n":"b","id":"a3.lb","t":"să protejeze și să promoveze bunăstarea copilului;","lvl":2},{"k":"lit","n":"c","id":"a3.lc","t":"să asigure protecția copilului de orice violență fizică, sexuală, psihologică, economică, spirituală;","lvl":2},{"k":"lit","n":"d","id":"a3.ld","t":"să informeze părinții și/sau autoritatea tutelară despre orice schimbare în situația familiei sale sau a copilului, care ar putea afecta capacitatea de a îngriji și educa copilul;","lvl":2},{"k":"lit","n":"e","id":"a3.le","t":"să înștiințeze imediat, dar nu mai târziu de 24 de ore, părinții despre orice maladie a copilului și despre interacțiunea copilului cu organele de drept în calitate de bănuit, învinuit, inculpat, victimă sau martor;","lvl":2},{"k":"lit","n":"f","id":"a3.lf","t":"să asigure comunicarea copilului cu părinții, bunicii, frații și surorile și cu alte persoane apropiate pentru copil, dacă aceasta nu contravine interesului superior al copilului;","lvl":2},{"k":"lit","n":"g","id":"a3.lg","t":"să asigure copilului condiții adecvate de trai și de igienă personală, precum și să îl asiste în formarea deprinderilor de autoîngrijire;","lvl":2},{"k":"lit","n":"h","id":"a3.lh","t":"să asigure copilul cu îmbrăcăminte și încălțăminte în conformitate cu necesitățile și particularitățile individuale ale acestuia, cu opinia părinților și cea a copilului, implicându-l,","lvl":2},{"k":"p","id":"a3.x1","t":"după caz, în alegerea și procurarea îmbrăcămintei și încălțămintei sau oferindu-i posibilitatea de a alege și a procura de sine stătător bunurile respective;","lvl":1,"cont":true},{"k":"lit","n":"i","id":"a3.li","t":"să asigure copilului o alimentație sănătoasă, care corespunde cu particularitățile de vârstă, cu necesitățile fiziologice ale acestuia, precum şi cu preferințele copilului;","lvl":2},{"k":"lit","n":"j","id":"a3.lj","t":"să faciliteze înscrierea copilului în instituții de învățământ, ținând cont de opinia părinților și cea a copilului, precum și de necesitățile educaționale și de dezvoltare ale copilului;","lvl":2},{"k":"lit","n":"k","id":"a3.lk","t":"să contribuie la petrecerea timpului liber de către copil și la implicarea acestuia în activități sportive, culturale și artistice, conform intereselor copilului;","lvl":2},{"k":"lit","n":"l","id":"a3.ll","t":"să verifice și, după caz, să întreprindă măsurile necesare pentru a asigura luarea în evidență a copilului de către medicul de familie în cel mult 5 zile de la data instituirii custodiei;","lvl":2},{"k":"lit","n":"m","id":"a3.lm","t":"să asigure prezența copilului la examenele medicale, conform prescrierilor medicului de familie și ale medicilor specialiști;","lvl":2},{"k":"lit","n":"n","id":"a3.ln","t":"să respecte prescrierile medicilor, să aplice cu strictețe tratamentul copilului și să realizeze măsuri de prevenire a îmbolnăvirii;","lvl":2},{"k":"lit","n":"o","id":"a3.lo","t":"să aplice metode de educație adecvate atât vârstei, cât și problemelor cu care se confruntă copilul, pentru a-i forma deprinderi privind modul sănătos de viață, respectarea igienei personale, alimentarea rațională şi inofensivă;","lvl":2},{"k":"lit","n":"p","id":"a3.lp","t":"să anunțe autoritatea tutelară locală care a dispus instituirea custodiei în cazurile în care părinții nu asigură/asigură insuficient surse financiare și bunuri necesare pentru creșterea și îngrijirea copilului și/sau nu se implică în procesul de educație a copilului;","lvl":2},{"k":"lit","n":"q","id":"a3.lq","t":"să asigure protecția și confidențialitatea datelor cu caracter personal, cunoscute în exercitarea atribuțiilor de custode.","lvl":2},{"k":"al","n":"4","id":"a4","t":"Drepturile și obligațiile custodelui sunt exercitate de către acesta numai pe perioada aflării efective a copilului în îngrijirea sa.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Cheltuielile pentru creșterea, îngrijirea și educația copiilor aflați în custodie sunt suportate de către reprezentantul legal, inclusiv din contul prestațiilor sociale acordate pentru copiii respectivi.","lvl":1}]},{"id":"13_4","num":"13⁴","title":"Monitorizarea situației copiilor ai căror părinți/unicul părinte sau tutore/curator se află temporar în altă localitate din țară sau de peste hotare","node":"n4","blocks":[{"k":"al","n":"1","id":"a1","t":"Monitorizarea situației copiilor ai căror părinți/unicul părinte sau tutore/curator se află temporar în altă localitate din țară sau de peste hotare se realizează semestrial de către autoritatea tutelară locală de la locul aflării copilului, prin intermediul specialistului în protecția drepturilor copilului sau, în lipsa acestuia, al asistentului social comunitar, în perioada 1–31 mai și, respectiv, 1–30 noiembrie, în baza:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"listelor copiilor ai căror părinți/unicul părinte sau tutore/curator se află temporar în altă localitate din țară sau de peste hotare, prezentate de către conducerea instituțiilor de învățământ până la data de 30 aprilie și, respectiv, de 30 octombrie;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"informațiilor privind identificarea copiilor ai căror părinți/unicul părinte sau tutore/curator se află temporar în altă localitate din țară sau de peste hotare, prezentate de specialistul în protecția drepturilor copilului, asistentul social comunitar, medicul de familie/asistentul medicului de familie sau ofițerul de sector al poliției;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"Registrului privind evidența copiilor aflați în custodie, contrapus cu listele și informațiile indicate la lit. a) și b).","lvl":2,"r":[[107,114,{"lit":"a","art":"13_4","al":"1"}],[118,120,{"lit":"b","art":"13_4","al":"1"}]]},{"k":"al","n":"2","id":"a2","t":"Dacă în rezultatul monitorizării situației copiilor ai căror părinți/unicul părinte sau tutore/curator se află temporar în altă localitate din țară sau de peste hotare se constată că copilul întâmpină dificultăți în interacțiunea cu custodele și/sau membrii familiei acestuia, în procesul de educație, de relaționare cu alți copii sau cu cadrele didactice, autoritatea tutelară locală de la locul aflării copilului întreprinde măsuri de suport pentru depășirea situațiilor respective, cu implicarea, după caz, a părinților, ținând cont de interesul superior al copilului.","lvl":1}]},{"id":"13_5","num":"13⁵","title":"Încetarea custodiei","node":"n4","blocks":[{"k":"al","n":"1","id":"a1","t":"Custodia încetează:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"în cazul în care copilul a revenit în grija reprezentantului legal;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"la cererea părinților privind schimbarea custodelui;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"la cererea custodelui, cu înștiințarea prealabilă a părinților;","lvl":2},{"k":"lit","n":"d","id":"a1.ld","t":"în cazul revocării custodelui în condițiile art. 13⁶;","lvl":2,"r":[[44,52,{"art":"13_6"}]]},{"k":"lit","n":"e","id":"a1.le","t":"în cazul decesului custodelui sau al copilului.","lvl":2},{"k":"note","t":"[Art.13⁵ al.(1), lit.e) introdusă prin LP167 din 30.07.26, MO435-438/09.09.26 art. 452; în vigoare 09.12.26]","id":"n1","lvl":0},{"k":"al","n":"2","id":"a2","t":"În cazurile indicate la alin.(1), autoritatea tutelară locală care a instituit custodia emite, în termen de 3 zile lucrătoare, dispoziția privind încetarea custodiei.","lvl":1,"r":[[24,32,{"al":"1","art":"13_5"}]]}]},{"id":"13_6","num":"13⁶","title":"Revocarea calității de custode","node":"n4","blocks":[{"k":"al","n":"1","id":"a1","t":"Copilul, părinții acestuia, persoanele împuternicite prin lege cu atribuții de protecție a copilului, precum și alte persoane pot contesta sau denunța la autoritatea tutelară locală actele și acțiunile custodelui care prejudiciază drepturile și interesele copilului.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Custodele este revocat de către autoritatea tutelară locală dacă a admis săvârșirea actelor de violență împotriva copilului, de neglijență sau care lezează drepturile copilului, precum şi dacă nu-și exercită corespunzător atribuțiile stipulate. Constatarea faptelor respective se efectuează conform instrucțiunilor privind mecanismul intersectorial de cooperare pentru identificarea, evaluarea, referirea, asistența și monitorizarea copiilor victime și potențiale victime ale violenței, neglijării, exploatării și ale traficului, aprobate de către Guvern.","lvl":1}]},{"id":"14","num":"14","title":"Copiii rămaşi temporar fără ocrotire părintească","node":"n5","blocks":[{"k":"al","n":"1","id":"a1","t":"Statutul de copil rămas temporar fără ocrotire părintească se atribuie copiilor:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"ai căror părinți lipsesc o perioadă mai mare de 30 de zile din cauza aflării la tratament în condiții de staționar în instituții medicale, fapt confirmat de certificatul medical eliberat de instituția medicală corespunzătoare;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"ai căror părinţi nu au posibilitatea să-şi îndeplinească obligaţiile de creştere şi educare a copiilor din cauza unor probleme grave de sănătate, fiind imobilizați la pat, sau din cauza unei dizabilități severe, fapt confirmat de certificatul consiliului de expertiză medicală a vitalităţii sau de certificatul medical eliberat de instituţia medicală care supraveghează pacientul;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"ai căror părinţi se află în arest, fapt confirmat printr-o hotărâre a instanţei de judecată;","lvl":2},{"k":"lit","n":"d","id":"a1.ld","t":"luați de la părinţi fără ca aceștia să fie decăzuți din drepturile părinteşti, fapt confirmat printr-o hotărâre a instanţei de judecată;","lvl":2},{"k":"lit","n":"e","id":"a1.le","t":"ai căror părinţi lipsesc, fiind anunţaţi în căutare de către organele de drept pentru comiterea de infracţiuni, fapt confirmat printr-un act eliberat de organul de poliţie;","lvl":2},{"k":"lit","n":"f","id":"a1.lf","t":"ai căror părinţi au fost pedepsiţi cu privaţiune de libertate, fapt confirmat printr-o hotărâre a instanţei de judecată;","lvl":2},{"k":"lit","n":"g","id":"a1.lg","t":"ale căror date de identitate nu sunt cunoscute;","lvl":2},{"k":"lit","n":"h","id":"a1.lh","t":"în privința părinților cărora se află în derulare procese judiciare privind decăderea din drepturile părintești, privind instituirea măsurii de ocrotire judiciare sau privind declararea lor ca fiind dispăruți fără urmă sau decedați;","lvl":2},{"k":"lit","n":"i","id":"a1.li","t":"străini care au intrat pe teritoriul Republicii Moldova fără a fi însoțiți de o persoană adultă responsabilă pentru ei prin lege sau care au fost lăsați pe teritoriul Republicii Moldova fără un act juridic, fapt confirmat printr-un proces-verbal întocmit de către autoritatea tutelară locală.","lvl":2},{"k":"note","t":"[Art.14 al.(1), lit.i) introdusă prin LP167 din 30.07.26, MO435-438/09.09.26 art. 452; în vigoare 09.12.26]","id":"n1","lvl":0},{"k":"al","n":"2","id":"a2","t":"Statutul de copil rămas temporar fără ocrotire părintească se retrage în cazurile:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"recunoaşterii sau stabilirii paternităţii, conform prevederilor art. 47 alin.(5)–(6) și art. 48 din Codul familiei;","lvl":2,"r":[[64,84,{"art":"47","al":"5","al2":"6","a":"cod:familiei"}],[88,95,{"art":"48","a":"cod:familiei"}],[100,114,{"a":"cod:familiei","whole":true}]]},{"k":"lit","n":"b","id":"a2.lb","t":"încetării circumstanţelor prevăzute la alin.(1) lit. a) şi b) din prezentul articol şi constatării faptului că părinţii/unicul părinte sunt apţi să-şi îndeplinească drepturile şi obligaţiile privind creşterea şi educaţia copiilor, fapt confirmat prin avizul autorităţii tutelare locale în a cărei rază domiciliază părinţii;","lvl":2,"r":[[39,55,{"al":"1","lit":"a","art":"14"}],[59,61,{"al":"1","lit":"b","art":"14"}]]},{"k":"lit","n":"c","id":"a2.lc","t":"prezentării adeverinţei de eliberare dintr-o instituţie penitenciară sau de sub arest a mamei/tatălui copilului şi a cererii acestora cu privire la înapoierea copilului, depusă la autoritatea tutelară teritorială care a stabilit statutul copilului, precum şi a avizului autorităţii tutelare locale în a cărei rază domiciliază părinţii privind oportunitatea înapoierii copilului pentru educaţie mamei/tatălui, întocmit în urma evaluării de către asistentul social comunitar a garanţiilor morale şi a condiţiilor materiale ale părinţilor;","lvl":2},{"k":"lit","n":"d","id":"a2.ld","t":"anulării hotărârii instanţei de judecată privind luarea copilului de la părinţi fără ca aceștia să fie decăzuți din drepturile părinteşti;","lvl":2},{"k":"lit","n":"e","id":"a2.le","t":"pronunţării hotărârii instanţei de judecată privind înapoierea copilului care a fost luat de la părinţi fără ca aceștia sa fie decăzuți din drepturile părinteşti conform procedurii judiciare;","lvl":2},{"k":"lit","n":"f","id":"a2.lf","t":"scoaterii mamei/tatălui de sub urmărire penală sau încetării urmăririi penale în condiţiile art. 284 şi 285 din Codul de procedură penală;","lvl":2,"r":[[92,100,{"art":"284","a":"cod:procedura penala"}],[104,107,{"art":"285","a":"cod:procedura penala"}],[112,137,{"a":"cod:procedura penala","whole":true}]]},{"k":"lit","n":"g","id":"a2.lg","t":"atingerii de către copil a vârstei la care are capacitatea deplină de exerciţiu;","lvl":2},{"k":"lit","n":"h","id":"a2.lh","t":"obţinerii documentelor ce confirmă identitatea copilului ale cărui date de identitate nu erau cunoscute, precum și a datelor despre părinţii lui, în baza avizului autorităţii tutelare locale în a cărei rază domiciliază părinţii privind oportunitatea înapoierii copilului, întocmit în urma evaluării de către asistentul social comunitar a garanţiilor morale şi a condiţiilor materiale ale părinţilor.","lvl":2}]},{"id":"15","num":"15","title":"Copiii rămaşi fără ocrotire părintească","node":"n5","blocks":[{"k":"al","n":"1","id":"a1","t":"Statutul de copil rămas fără ocrotire părintească se atribuie copiilor ai căror părinţi:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"sunt decedaţi, fapt confirmat printr-un certificat de deces;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"au fost decăzuţi din drepturile părinteşti, fapt confirmat printr-o hotărâre a instanţei de judecată;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"sunt supuşi unei măsuri de ocrotire judiciare, fapt confirmat prin hotărâre a instanței de judecată;","lvl":2},{"k":"lit","n":"d","id":"a1.ld","t":"au fost declaraţi dispăruţi fără urmă, fapt confirmat printr-o hotărâre a instanţei de judecată;","lvl":2},{"k":"lit","n":"e","id":"a1.le","t":"au fost declaraţi decedaţi, fapt confirmat printr-o hotărâre a instanţei de judecată;","lvl":2},{"k":"lit","n":"f","id":"a1.lf","t":"i-au abandonat, fapt confirmat printr-o hotărâre a instanţei de judecată.","lvl":2},{"k":"al","n":"2","id":"a2","t":"Statutul de copil rămas fără ocrotire părintească se retrage în cazurile:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"anulării hotărârii instanţei de judecată privind decăderea din drepturile părinteşti a părinților copilului;","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"restabilirii în drepturile părinteşti a mamei/tatălui copilului;","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"adopţiei copilului, încuviinţată printr-o hotărâre a instanţei de judecată;","lvl":2},{"k":"lit","n":"d","id":"a2.ld","t":"recunoaşterii sau stabilirii paternităţii, conform prevederilor art. 47 alin. (5) și (6) și art. 48 din Codul familiei;","lvl":2,"r":[[64,81,{"art":"47","al":"5","a":"cod:familiei"}],[85,88,{"art":"47","al":"6","a":"cod:familiei"}],[92,99,{"art":"48","a":"cod:familiei"}],[104,118,{"a":"cod:familiei","whole":true}]]},{"k":"lit","n":"e","id":"a2.le","t":"expirării sau revocării măsurii de ocrotire judiciare instituite în privinţa mamei/tatălui copilului;","lvl":2},{"k":"lit","n":"f","id":"a2.lf","t":"pronunțării hotărârii instanţei de judecată privind declararea capacităţii de exerciţiu depline a mamei/tatălui copilului;","lvl":2},{"k":"lit","n":"g","id":"a2.lg","t":"anulării hotărârii instanţei de judecată privind declararea mamei/tatălui copilului ca fiind dispărută/dispărut fără urmă;","lvl":2},{"k":"lit","n":"h","id":"a2.lh","t":"anulării hotărârii instanţei de judecată privind declararea mamei/tatălui copilului ca fiind decedată/decedat;","lvl":2},{"k":"lit","n":"i","id":"a2.li","t":"atingerii de către copil a vârstei la care are capacitatea deplină de exerciţiu.","lvl":2}]},{"id":"16","num":"16","title":"Termenul de determinare a statutului de copil rămas temporar fără ocrotire părintească sau de copil rămas fără ocrotire părintească","node":"n5","blocks":[{"k":"al","n":"1","id":"a1","t":"Autoritatea tutelară teritorială în evidenţa căreia se află copilul, în cooperare cu autoritatea tutelară locală, întreprinde acţiunile necesare pentru (re)integrarea în familie a copilului sau pentru stabilirea statutului copilului, acţiuni care, cumulativ, nu vor depăşi 6 luni.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Măsurile de (re)integrare a copilului în familie se efectuează conform unui plan individual de asistenţă.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Statutul copilului se stabilește din data la care au fost întrunite condițiile corespunzătoare, în conformitate cu art. 14, 15 și art. 17 alin. (2).","lvl":1,"r":[[115,122,{"art":"14"}],[124,126,{"art":"15"}],[130,147,{"art":"17","al":"2"}]]},{"k":"al","n":"4","id":"a4","t":"Acțiunile ce țin de stabilirea statutului copilului sunt realizate în mod prioritar.","lvl":1}]},{"id":"17","num":"17","title":"Stabilirea statutului copilului","node":"n5","blocks":[{"k":"al","n":"1","id":"a1","t":"Dispoziţia privind stabilirea sau retragerea statutului de copil rămas temporar fără ocrotire părintească sau de copil rămas fără ocrotire părintească se emite de către autoritatea tutelară teritorială.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Concomitent cu emiterea dispoziţiei privind stabilirea statutului de copil rămas fără ocrotire părintească, autoritatea tutelară teritorială emite dispoziţia privind stabilirea statutului de copil adoptabil, luarea în evidenţă a acestuia şi întreprinderea măsurilor de adopţie a copilului conform prevederilor legislaţiei, cu excepţia copiilor rămaşi fără ocrotire părintească care sunt plasaţi sub tutelă/curatelă în familia extinsă.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Pe parcursul procesului de stabilire a statutului, autoritatea tutelară este obligată să asigure copilului informații și explicații clare și complete, potrivit vârstei și gradului său de maturitate, privind etapele și durata procesului de stabilire a statutului, privind efectele acestuia și formele de protecție aplicabile.","lvl":1},{"k":"al","n":"4","id":"a4","t":"În procesul de stabilire a statutului și de identificare a serviciului de plasament se ține cont de opinia, de dorințele și de sentimentele copilului în funcție de vârsta și gradul său de maturitate.","lvl":1}]},{"id":"18","num":"18","title":"Evidenţa copiilor separaţi de părinţi","node":"n5","blocks":[{"k":"al","n":"1","id":"a1","t":"Evidenţa copiilor separaţi de părinţi se ține de către:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"autoritatea tutelară locală care a dispus plasamentul de urgență al copilului sau cea de la domiciliul custodelui;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"autoritatea tutelară teritorială care a emis dispoziţia de plasament planificat;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"autoritatea centrală pentru protecţia copilului, pe baza datelor prezentate de autorităţile tutelare teritoriale.","lvl":2},{"k":"al","n":"2","id":"a2","t":"Registrele de evidenţă a copiilor separaţi de părinţi se țin de către autoritatea tutelară locală şi de către specialiştii responsabili din cadrul autorităţilor tutelare teritoriale.","lvl":1}]},{"id":"19","num":"19","title":"Cooperarea dintre autorităţile tutelare","node":"n6","blocks":[{"k":"p","id":"x1","t":"Autorităţile tutelare locale şi cele teritoriale din diferite unităţi administrativ-teritoriale sunt obligate să coopereze în domeniul protecţiei copilului prin obţinerea şi transmiterea informaţiilor şi a documentelor necesare pentru identificarea, evaluarea, acordarea asistenţei şi stabilirea statutului copiilor.","lvl":1}]},{"id":"20","num":"20","title":"Cooperarea intersectorială","node":"n6","blocks":[{"k":"p","id":"x1","t":"Angajații autorităţilor publice centrale şi locale, ai structurilor, instituţiilor şi serviciilor din cadrul sau subordonate acestora, care activează în domeniile asistenţei sociale, educației, ocrotirii sănătăţii, organelor de drept în conformitate cu mecanismele de cooperare intersectorială aprobate de către Guvern sunt obligați:","lvl":1},{"k":"lit","n":"a","id":"la","t":"să transmită autorităţii tutelare competente sesizările privind copiii aflați în situaţie de risc, precum şi cele privind cazurile de abuz, neglijare sau exploatare a copiilor în cadrul serviciilor sociale, al instituţiilor medicale, educaționale, culturale;","lvl":1},{"k":"lit","n":"b","id":"lb","t":"să participe la activitatea echipelor multidisciplinare în procesul de evaluare iniţială şi complexă a situaţiei copilului la solicitarea autorității tutelare locale, precum şi la elaborarea şi implementarea planului individualizat de asistenţă;","lvl":1},{"k":"lit","n":"c","id":"lc","t":"să întreprindă măsurile ce se impun pentru prevenirea primară a riscurilor privind bunăstarea copilului.","lvl":1}]},{"id":"21","num":"21","title":"Respectarea termenelor şi procedurilor în activitatea autorităţilor tutelare","node":"n7","blocks":[{"k":"al","n":"1","id":"a1","t":"Autorităţile tutelare sunt obligate să respecte temenele şi procedurile în procesul de identificare, luare în evidenţă, plasament, stabilire a statutului, monitorizare a situaţiei copiilor şi de prezentare a informaţiei autorităţilor de resort conform prevederilor prezentei legi, ale regulamentului de activitate aprobat de Guvern şi ale altor acte normative.","lvl":1},{"k":"al","n":"1¹","id":"a1_1","t":"Informația solicitată de autoritatea centrală pentru protecția copilului se prezintă de către autoritățile tutelare în termen de 10 zile lucrătoare, dacă în solicitare nu este stabilit un alt termen.","lvl":1},{"k":"al","n":"2","id":"a2","t":"În caz de nerespectare a termenelor şi procedurilor prevăzute de legislaţie, persoanele responsabile pot fi trase la răspundere în condiţiile legii.","lvl":1}]},{"id":"22","num":"22","title":"Răspunderea pentru încălcarea prezentei legi","node":"n7","blocks":[{"k":"al","n":"1","id":"a1","t":"Încălcarea prevederilor prezentei legi atrage răspunderea disciplinară, civilă, contravenţională sau penală, în conformitate cu legislaţia în vigoare.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Sunt pasibile de răspundere următoarele acţiuni/inacţiuni ale autorităţilor, instituţiilor sau persoanelor responsabile:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"nerespectarea condiţiilor legale de recepţionare şi înregistrare a sesizărilor privind copiii aflați în situaţie de risc;","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"încălcarea fără motive întemeiate a termenului stabilit de lege pentru iniţierea sau desfăşurarea procedurii de evaluare iniţială a situaţiei copilului şi de stabilire a statutului acestuia ori de (re)integrare a acestuia în familie;","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"asistenţa sau monitorizarea necorespunzătoare a copiilor aflați în situaţie de risc, a copiilor rămaşi temporar fără ocrotire părintească sau a copiilor rămaşi fără ocrotire părintească;","lvl":2},{"k":"lit","n":"d","id":"a2.ld","t":"tergiversarea fără motive întemeiate a prezentării către autoritatea centrală pentru protecţia copilului a informaţiei despre copiii separaţi de părinţi, copiii rămaşi temporar fără ocrotire părintească şi copiii rămaşi fără ocrotire părintească;","lvl":2},{"k":"lit","n":"e","id":"a2.le","t":"neasigurarea controlului asupra condiţiilor de întreţinere, educaţie şi instruire în familie a copiilor aflați în situaţie de risc care sunt în evidenţă, precum şi a copiilor aflaţi în plasament;","lvl":2},{"k":"lit","n":"f","id":"a2.lf","t":"plasarea neîntemeiată sau cu încălcarea condiţiilor stabilite de lege în serviciul de plasament de tip rezidenţial a copilului separat de părinţi, a celui rămas temporar fără ocrotire părintească sau a celui rămas fără ocrotire părintească;","lvl":2},{"k":"lit","n":"g","id":"a2.lg","t":"încălcarea fără motive întemeiate a termenului prevăzut de legislaţie pentru sesizarea autorităţii tutelare privind copiii aflați în situaţie de risc;","lvl":2},{"k":"lit","n":"h","id":"a2.lh","t":"neîndeplinirea, fără motive întemeiate, de către părinţi, de către persoanele care îi înlocuiesc sau de către persoanele în grija cărora copiii se află potrivit legii a dispoziţiilor legitime ale autorităţii tutelare în scopul asigurării respectării drepturilor şi intereselor copiilor;","lvl":2},{"k":"lit","n":"i","id":"a2.li","t":"neîndeplinirea sau îndeplinirea necorespunzătoare de către părinţi sau de către persoanele care îi înlocuiesc a obligaţiilor părinteşti, dacă aceasta a determinat plasamentul de urgenţă al copilului;","lvl":2},{"k":"lit","n":"j","id":"a2.lj","t":"eschivarea sub orice formă a părinţilor sau a persoanelor care îi înlocuiesc de la procesul de reintegrare a copilului în familie;","lvl":2},{"k":"lit","n":"k","id":"a2.lk","t":"aflarea copilului în pericol iminent din cauza lipsei de supraveghere din partea părinților, a reprezentanților legali sau a altor persoane în grija cărora acesta se află.","lvl":2},{"k":"al","n":"3","id":"a3","t":"Prejudiciul material sau cel moral cauzat copilului de către persoane fizice sau juridice urmează a fi reparat în modul stabilit de lege.","lvl":1}]},{"id":"23","num":"23","title":"","node":"n8","blocks":[{"k":"al","n":"1","id":"a1","t":"Prezenta lege intră în vigoare de la 1 ianuarie 2014.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Guvernul, în termen de 6 luni de la data intrării în vigoare a prezentei legi:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"va prezenta Parlamentului propuneri privind aducerea legislaţiei în vigoare în concordanţă cu prezenta lege;","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"va aduce actele sale normative în concordanţă cu prezenta lege;","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"va elabora şi va adopta actele normative necesare pentru implementarea prezentei legi.","lvl":2},{"k":"al","n":"3","id":"a3","t":"La data intrării în vigoare a prezentei legi, Codul familiei nr. 1316-XIV din 26 octombrie 2000 (Monitorul Oficial al Republicii Moldova, 2001, nr. 47–48, art. 210), cu modificările ulterioare, se modifică după cum urmează:","lvl":1,"r":[[46,95,{"a":"cod:familiei","whole":true}],[155,163,{"art":"210","a":"cod:familiei"}]]},{"k":"p","id":"a3.x1","t":"1. La articolul 3, textul „condiţiile, modalitatea, formele şi efectele protecţiei juridice a copiilor orfani şi a celor rămaşi fără ocrotire părintească sau aflaţi în alte situaţii vulnerabile” se exclude.","lvl":1,"cont":true,"r":[[6,17,{"art":"3","a":"cod:familiei"}]]},{"k":"p","id":"a3.x2","t":"2. La articolul 71 alineatul (3), textul „7 zile” se substituie cu textul „3 zile lucrătoare”.","lvl":1,"cont":true,"r":[[6,32,{"art":"71","al":"3","a":"cod:familiei"}]]},{"k":"p","id":"a3.x3","t":"3. Capitolul 17 se abrogă.","lvl":1,"cont":true}]}],"annexes":[]};
